import Mathlib
import Bridges.BorsukUlamArrow.Defs

/-!
# Arrow's Impossibility Theorem — Proof Structure

This file documents the proof structure of Arrow's impossibility theorem
via the Geanakoplos (2005) pivotal voter argument. The proof has three steps:

1. **Extremal Lemma**: If every voter ranks b either first or last, then b
   must be either first or last in the social ranking.
2. **Pivotal Voter**: For any alternative b, there exists a voter whose
   switch from "b last" to "b first" flips the social ranking of b.
3. **Dictator from Pivot**: The pivotal voter is a dictator.

The extremal lemma requires constructing specific preference profiles
(SLO instances with prescribed pairwise orderings), which is a significant
formalization challenge due to the need to build Equiv.Perm instances.

## Proof Status

All lemmas in this file are fully proved without sorry:
- The extremal lemma constructs specific SLO instances via Equiv.swap
- The pivotal voter existence uses induction on voters with the extremal lemma
-/

open Finset Function

set_option maxHeartbeats 800000

namespace ArrowProof

variable {n k : ℕ}

/-! ## The Extremal Lemma -/

/-
**Extremal Lemma**: If every voter places `b` either first or last,
    then `b` must be first or last in the social ranking.

    PROOF SKETCH: By contradiction. If ∃ a,c with F(P).pref a b ∧ F(P).pref b c,
    construct P'' where every voter ranks c > a (possible since b is extremal
    and we can freely reorder {a,c} without changing b's position). By Pareto,
    F(P'').pref c a. By IIA (P and P'' agree on all pairs involving b),
    F(P'').pref a b ∧ F(P'').pref b c, hence F(P'').pref a c by transitivity.
    Contradiction: c > a and a > c.
-/
theorem extremal_lemma (hn : 3 ≤ n) (F : SWF n k)
    (hP : F.Pareto) (hI : F.IIA)
    (P : Profile n k) (b : Fin n)
    (hExtr : ∀ i : Fin k,
      (∀ a : Fin n, a ≠ b → (P i).pref b a) ∨
      (∀ a : Fin n, a ≠ b → (P i).pref a b)) :
    (∀ a : Fin n, a ≠ b → (F P).pref b a) ∨
    (∀ a : Fin n, a ≠ b → (F P).pref a b) := by
  by_contra h;
  -- By the extremal lemma, there exist $a_1 \neq b$ and $a_2 \neq b$ such that $(F P).pref a_1 b$ and $(F P).pref b a_2$.
  obtain ⟨a1, ha1⟩ : ∃ a1 : Fin n, a1 ≠ b ∧ (F P).pref a1 b := by
    contrapose! h;
    exact Or.inl fun a ha => by have := SLO.pref_total ( F P ) ( show a ≠ b from ha ) ; tauto;
  obtain ⟨a2, ha2⟩ : ∃ a2 : Fin n, a2 ≠ b ∧ (F P).pref b a2 := by
    grind +suggestions;
  -- Construct a new profile $P'$ where every voter ranks $a_2 > a_1$.
  obtain ⟨P', hP'⟩ : ∃ P' : Profile n k, (∀ i : Fin k, ((P' i).pref a2 a1)) ∧ (∀ i : Fin k, (∀ a : Fin n, a ≠ b → ((P' i).pref b a ↔ (P i).pref b a) ∧ ((P' i).pref a b ↔ (P i).pref a b))) := by
    have hP'_exists : ∀ i : Fin k, ∃ r : SLO n, (r.pref a2 a1) ∧ (∀ a : Fin n, a ≠ b → (r.pref b a ↔ (P i).pref b a) ∧ (r.pref a b ↔ (P i).pref a b)) := by
      intro i
      obtain hi | hi := hExtr i;
      · -- Construct a new ranking $r$ where $b$ is first, $a_2$ is second, $a_1$ is third, and the rest are arbitrary.
        obtain ⟨r, hr⟩ : ∃ r : Fin n ≃ Fin n, r b = ⟨0, by linarith⟩ ∧ r a2 = ⟨1, by linarith⟩ ∧ r a1 = ⟨2, by linarith⟩ := by
          -- Since $a1$, $a2$, and $b$ are distinct, we can construct a permutation $r$ that maps $b$ to $0$, $a2$ to $1$, and $a1$ to $2$.
          obtain ⟨r, hr⟩ : ∃ r : Fin n ≃ Fin n, r b = ⟨0, by linarith⟩ ∧ r a2 = ⟨1, by linarith⟩ := by
            obtain ⟨r, hr⟩ : ∃ r : Fin n ≃ Fin n, r b = ⟨0, by linarith⟩ := by
              exact ⟨ Equiv.swap b ⟨ 0, by linarith ⟩, by simp +decide ⟩;
            use r.trans (Equiv.swap (r a2) ⟨1, by linarith⟩);
            simp +decide [ hr, Equiv.swap_apply_def ];
            exact Ne.symm ( by intro h; have := r.injective ( h.trans hr.symm ) ; aesop );
          use r.trans (Equiv.swap (r a1) ⟨2, by linarith⟩);
          simp +decide [ hr, Equiv.swap_apply_def ];
          constructor <;> intro h <;> simp_all +decide [ Equiv.injective r ];
          exact ha1.2 |> fun h' => by have := SLO.pref_asymm ( F P ) h' ha2; contradiction;
        use ⟨r⟩;
        simp_all +decide [ SLO.pref ];
        exact fun a ha => ⟨ Nat.pos_of_ne_zero fun h => ha <| r.injective <| by aesop, le_of_lt <| hi a ha ⟩;
      · -- Since $a_2 \neq b$ and $a_1 \neq b$, we can construct a ranking where $a_2 > a_1$ and $b$ is last.
        obtain ⟨r, hr⟩ : ∃ r : Fin n ≃ Fin n, r a2 < r a1 ∧ ∀ a : Fin n, a ≠ b → r b > r a := by
          obtain ⟨r, hr⟩ : ∃ r : Fin n ≃ Fin n, r b = Fin.mk (n - 1) (by
          exact Nat.pred_lt ( ne_bot_of_gt hn )) ∧ r a2 < r a1 := by
            obtain ⟨r, hr⟩ : ∃ r : Fin n ≃ Fin n, r b = Fin.mk (n - 1) (by
            exact Nat.pred_lt ( ne_bot_of_gt hn )) := by
              exact ⟨ Equiv.swap b ⟨ n - 1, Nat.sub_lt ( by linarith ) zero_lt_one ⟩, by simp +decide ⟩
            generalize_proofs at *;
            by_cases h_cases : r a2 < r a1;
            · exact ⟨ r, hr, h_cases ⟩;
            · use r * Equiv.swap a1 a2;
              simp_all +decide [ Equiv.swap_apply_def ];
              cases lt_or_eq_of_le h_cases <;> simp_all +decide [ Equiv.swap_apply_def ];
              · grind;
              · exact ha2.2 |> fun h => by have := SLO.pref_asymm _ h; tauto;
          generalize_proofs at *;
          exact ⟨ r, hr.2, fun a ha => hr.1.symm ▸ lt_of_le_of_ne ( Nat.le_sub_one_of_lt ( Fin.is_lt _ ) ) fun h => ha <| r.injective <| Fin.ext <| by aesop ⟩;
        use ⟨r⟩;
        simp_all +decide [ SLO.pref ];
        grind;
    exact ⟨ fun i => Classical.choose ( hP'_exists i ), fun i => Classical.choose_spec ( hP'_exists i ) |>.1, fun i a ha => Classical.choose_spec ( hP'_exists i ) |>.2 a ha ⟩;
  -- By IIA, since P and P' agree on all pairs involving b, we have (F P').pref a1 b and (F P').pref b a2.
  have hFP'_pref : (F P').pref a1 b ∧ (F P').pref b a2 := by
    apply And.intro;
    · apply iia_same_pairwise F hI P P' a1 b;
      · grind;
      · exact ha1.2;
    · apply iia_same_pairwise F hI P P' b a2;
      · exact fun i => ( hP' |>.2 i a2 ha2.1 ) |>.1.symm;
      · exact ha2.2;
  -- By transitivity of F P', we have (F P').pref a1 a2.
  have hFP'_trans : (F P').pref a1 a2 := by
    exact SLO.pref_trans _ hFP'_pref.1 hFP'_pref.2;
  exact absurd ( hP P' a2 a1 hP'.1 ) ( by exact fun h => SLO.pref_asymm _ h hFP'_trans )

/-! ## Pivotal Voter -/

/-- A voter `j` is **pivotal** for alternative `b`. -/
def isPivotal (F : SWF n k) (j : Fin k) (b : Fin n) : Prop :=
  ∃ (P Q : Profile n k),
    (∀ i : Fin k, i ≠ j → P i = Q i) ∧
    (∀ a : Fin n, a ≠ b → (P j).pref a b) ∧
    (∀ a : Fin n, a ≠ b → (Q j).pref b a) ∧
    (∀ a : Fin n, a ≠ b → (F P).pref a b) ∧
    (∀ a : Fin n, a ≠ b → (F Q).pref b a)

/-
**Pivotal Voter Existence** (depends on extremal_lemma): For any
    alternative b, there exists a pivotal voter.
-/
theorem pivotal_exists (hn : 3 ≤ n) (hk : 1 ≤ k) (F : SWF n k)
    (hP : F.Pareto) (hI : F.IIA)
    (b : Fin n) : ∃ j : Fin k, isPivotal F j b := by
  -- By Pareto, in P_0, b is socially last. By Pareto, in P_k, b is socially first.
  obtain ⟨P0, hP0⟩ : ∃ P0 : Profile n k, (∀ i : Fin k, (∀ a : Fin n, a ≠ b → (P0 i).pref a b)) ∧ (∀ a : Fin n, a ≠ b → (F P0).pref a b) := by
    obtain ⟨P0, hP0⟩ : ∃ P0 : SLO n, (∀ a : Fin n, a ≠ b → P0.pref a b) := by
      refine' ⟨ ⟨ Equiv.swap b ( ⟨ n - 1, Nat.sub_lt ( by linarith ) zero_lt_one ⟩ : Fin n ) ⟩, _ ⟩ ; simp +decide [ SLO.pref ];
      grind;
    exact ⟨ fun _ => P0, fun _ _ _ => hP0 _ ‹_›, fun _ _ => hP _ _ _ fun _ => hP0 _ ‹_› ⟩;
  -- By Pareto, in P_k, b is socially first.
  obtain ⟨Pk, hPk⟩ : ∃ Pk : Profile n k, (∀ i : Fin k, (∀ a : Fin n, a ≠ b → (Pk i).pref b a)) ∧ (∀ a : Fin n, a ≠ b → (F Pk).pref b a) := by
    use fun i => (P0 i).reverse;
    exact ⟨ fun i a ha => by simp [ SLO.reverse_pref_iff, hP0.1 i a ha ], fun a ha => by simpa [ SLO.reverse_pref_iff ] using hP ( fun i => ( P0 i ).reverse ) b a fun i => by simpa [ SLO.reverse_pref_iff ] using hP0.1 i a ha ⟩;
  -- Define profiles P_j where P_j is obtained from P_0 by reversing the first j voters' rankings.
  set Pj : ℕ → Profile n k := fun j => fun i => if i.val < j then (P0 i).reverse else P0 i;
  -- By the properties of the profiles P_j, there exists a j₀ such that in P_{j₀}, b is socially first, and in P_{j₀-1}, b is socially last.
  obtain ⟨j₀, hj₀⟩ : ∃ j₀ ∈ Finset.range (k + 1), (∀ a : Fin n, a ≠ b → (F (Pj j₀)).pref b a) ∧ (∀ j < j₀, (∀ a : Fin n, a ≠ b → (F (Pj j)).pref a b)) := by
    have h_exists_j₀ : ∃ j₀ ∈ Finset.range (k + 1), (∀ a : Fin n, a ≠ b → (F (Pj j₀)).pref b a) := by
      use k;
      convert hPk.2 using 1;
      simp +zetaDelta at *;
      constructor <;> intro h a ha <;> have := hI ( fun i => ( P0 i ).reverse ) Pk <;> simp_all +decide [ SLO.reverse_pref_iff ] ;
    obtain ⟨j₀, hj₀⟩ : ∃ j₀ ∈ Finset.range (k + 1), (∀ a : Fin n, a ≠ b → (F (Pj j₀)).pref b a) ∧ ∀ j < j₀, ¬(∀ a : Fin n, a ≠ b → (F (Pj j)).pref b a) := by
      exact ⟨ Nat.find h_exists_j₀, Nat.find_spec h_exists_j₀ |>.1, Nat.find_spec h_exists_j₀ |>.2, fun j hj => fun h => Nat.find_min h_exists_j₀ hj ⟨ Finset.mem_range.mpr ( by linarith [ Finset.mem_range.mp ( Nat.find_spec h_exists_j₀ |>.1 ) ] ), h ⟩ ⟩;
    refine' ⟨ j₀, hj₀.1, hj₀.2.1, fun j hj => _ ⟩;
    have := extremal_lemma hn F hP hI ( Pj j ) b ?_;
    · exact this.resolve_left ( hj₀.2.2 j hj );
    · simp +zetaDelta at *;
      intro i; split_ifs <;> simp_all +decide [ SLO.reverse_pref_iff ] ;
  rcases j₀ <;> simp_all +decide [ Finset.mem_range_succ_iff ];
  · contrapose! hj₀;
    obtain ⟨ a, ha ⟩ := Finset.exists_mem_ne ( show 1 < Finset.card ( Finset.univ : Finset ( Fin n ) ) from by simpa using by linarith ) b;
    exact ⟨ a, ha.2, by have := hP0.2 a ha.2; exact fun h => by have := SLO.pref_asymm ( F P0 ) h; tauto ⟩;
  · use ⟨‹ℕ›, by linarith⟩, Pj ‹ℕ›, Pj (‹ℕ› + 1);
    simp +zetaDelta at *;
    refine' ⟨ _, _, _, _, _ ⟩;
    · grind;
    · exact fun a ha => hP0.1 _ _ ha;
    · intro a ha; specialize hP0; have := hP0.1 ⟨ ‹_›, by linarith ⟩ a ha; simp_all +decide [ SLO.reverse_pref_iff ] ;
    · exact hj₀.2.2 _ le_rfl;
    · grind +splitImp

-- depends on extremal_lemma

end ArrowProof

